import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.InzUq-5O.js";const m=JSON.parse('{"title":"Lucide is the icon set everywhere","description":"","frontmatter":{"status":"accepted","date":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0024-lucide-is-the-icon-set.md","filePath":"docs/adr/0024-lucide-is-the-icon-set.md"}'),o={name:"docs/adr/0024-lucide-is-the-icon-set.md"};function n(r,e,c,d,h,l){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="lucide-is-the-icon-set-everywhere" tabindex="-1">Lucide is the icon set everywhere <a class="header-anchor" href="#lucide-is-the-icon-set-everywhere" aria-label="Permalink to &quot;Lucide is the icon set everywhere&quot;">​</a></h1><p>Every icon in Coach Poulpy comes from <a href="https://lucide.dev" target="_blank" rel="noreferrer">Lucide</a>: the websites, the web mockups and docs site (ADR 0023), the phone and tablet mockups, and the Android and iOS apps. One set means one drawing style, one stroke weight and one name for each action, whatever the platform.</p><h2 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h2><ul><li>A new icon is taken from Lucide by its Lucide name (<code>calendar</code>, <code>chevron-left</code>, <code>circle-alert</code>). A platform never draws its own icon for an action Lucide already has.</li><li>Each platform uses the Lucide package for its toolkit. Vue uses <a href="https://lucide.dev/docs/packages/lucide-vue-next" target="_blank" rel="noreferrer"><code>lucide-vue-next</code></a>, the official package. The Android (Compose) and iOS (SwiftUI) packages are not yet chosen: the Lucide package list was not checked when this was written, and the community ports found so far are not confirmed as official. Choosing them, and checking their licences and maintenance, is the follow-up issue (<a href="https://github.com/tkint/coach-poulpy/issues/282" target="_blank" rel="noreferrer">#282</a>).</li><li>Poulpy&#39;s drawings are not icons. They stay generated by <code>design/build-poulpy.mjs</code> (<a href="./0012-design-tokens-generated-from-one-file">ADR 0012</a>).</li><li>Icon colour comes from the colour roles in the <a href="./../design-system#colour-roles">design system</a>, never a raw palette step. An error keeps its icon: crimson, with words.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li>A person who learns one icon meaning in the app finds the same one on the website and in the docs.</li><li>One set can be used across Vue, Compose and SwiftUI with the same names, so mockups, screens and sites can be compared directly.</li><li>Lucide is open source under the ISC licence for its code. Most of its icons come from Feather and are under the MIT licence, which both allow use in the app and sites (<a href="https://lucide.dev/license" target="_blank" rel="noreferrer">Lucide license</a>).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Existing icons are not migrated by this decision. Migrating them is a separate issue (<a href="https://github.com/tkint/coach-poulpy/issues/282" target="_blank" rel="noreferrer">#282</a>), so this record changes no screen.</li><li>Until the migration is done, a mix of icon sets may exist. New icons use Lucide.</li><li>A screen or mockup that needs an icon Lucide lacks says so in its PR. The fix is a new drawing in <code>design/</code> that matches Lucide&#39;s stroke, not a different set.</li></ul>',8)])])}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
